parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "priorite_finale": {
      "type": "string",
      "enum": [
        "basse",
        "normale",
        "haute",
        "critique"
      ],
      "description": "Priorité réelle (alignée sur le CHECK SQL de tickets.priorite)"
    },
    "categorie": {
      "type": "string",
      "enum": [
        "infrastructure",
        "reseau",
        "application",
        "securite",
        "donnees",
        "acces_compte",
        "materiel",
        "autre"
      ]
    },
    "escalade_effectuee": {
      "type": "boolean",
      "description": "true uniquement si declencher_escalade_astreinte a été appelé"
    },
    "diagnostic_ia": {
      "type": "string",
      "description": "Justification factuelle en 2 à 3 phrases"
    }
  },
  "required": [
    "priorite_finale",
    "categorie",
    "escalade_effectuee",
    "diagnostic_ia"
  ],
  "additionalProperties": false
}

